function render(){try{const raw=Object.fromEntries(Object.keys(M.defaults).map(k=>[k,$('#input-'+k).value.trim()===''?NaN:Number($('#input-'+k).value)]));M.theory(raw);p=raw;built=C.build(p,rows,meta,view,mode);valid=true;$('#validation').textContent='';}catch(e){valid=false;$('#validation').textContent=e.message;$('#copy').disabled=true;return;}$('#copy').disabled=!importValid;const scroll=$('#code').scrollTop;let n=0;$('#code').innerHTML=built.blocks.map(b=>`<div class="logic-block" data-logic="${b.key}">${b.lines.map(l=>`<button class="code-line ${selected===b.key?'selected':''}" data-semantic="${b.key}"><span class="num">${++n}</span><code>${WorkbenchUI.colorCode(l)}</code></button>`).join('')}</div>`).join('');$('#code').scrollTop=scroll;const b=built.blocks.find(b=>b.key===selected)||built.blocks[0];$('#explanation').innerHTML='<h3>'+esc(b.title)+'</h3><p>'+esc(b.explain)+'</p>';$('#codeNotice').textContent=mode==='full'?'当前参数＋完整样本内嵌':'可独立运行；复制仍含完整绘图';document.querySelectorAll('[data-code-mode]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.codeMode===mode)));bar.querySelectorAll('button').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.capmView===view||(b.dataset.capmView==='scl'&&view==='residual'))));$('#field-sm').hidden=$('#field-w').hidden=view!=='cml';data.hidden=!['scl','residual'].includes(view);status();redraw();}
$('#inputs').oninput=()=>{const next=Object.fromEntries(Object.keys(M.defaults).map(k=>[k,$('#input-'+k).value.trim()===''?NaN:Number($('#input-'+k).value)]));try{M.theory(next);p=next;render();}catch(e){valid=false;ctrl.clear();$('#validation').textContent=e.message+' 请修正；上次图表仅供参考。';$('#copy').disabled=true;}};
bar.onclick=e=>{const b=e.target.closest('[data-capm-view]');if(b){view=b.dataset.capmView;selected=view;render();$('#code [data-semantic="'+selected+'"]')?.scrollIntoView({block:'nearest'});}};
$('#code').onclick=e=>{const b=e.target.closest('[data-semantic]');if(b){selected=b.dataset.semantic;render();}};
document.querySelectorAll('[data-code-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.codeMode;render();});
$('#copy').onclick=async()=>{if(!valid||!importValid)return;const text=C.build(p,rows,meta,view,'full').code;try{await navigator.clipboard.writeText(text);$('#codeNotice').textContent='已复制：含当前参数、全部样本与当前图';}catch{download('capm-full.R',text);}};
